//! 🎟️ Actual trace allocations, denied axes and final failures use the original retained work owner.
use super::*;
use semio_framework_value::RetainedCloneGrant;
use semio_framework_value_persistent::work::RetainedWorkLedger;
#[test]fn neutral_trace_original_work_funds_actual_heap_before_semantics(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();for row in law["cases"].as_array().unwrap(){let mask=row["mask"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as u8).collect::<Vec<_>>();let mut job=BitmapTraceJob::new(BitmapTraceInput{width:row["width"].as_u64().unwrap()as u32,height:row["height"].as_u64().unwrap()as u32,mask,threshold:0.5,simplify_epsilon:row["epsilon"].as_f64().unwrap(),max_pixels:9,max_edges:36,max_segments:45,max_work:1_000_000});let stock=&law["stock"];let original=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let mut wallet=trace_funding::Wallet::from_grant(original,law["maxTurns"].as_u64().unwrap()as usize);let mut remaining=original;let mut denied=[false;4];let mut complete=false;
  for turn in 0..law["maxTurns"].as_u64().unwrap(){let d=job.next_work_demand();let g=remaining;for axis in 0..4{let mut under=g;let field=match axis{0=>&mut under.maximum_items,1=>&mut under.maximum_copy_bytes,2=>&mut under.maximum_capacity_bytes,_=>&mut under.maximum_depth};let requested=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,_=>d.depth};if denied[axis]||requested==0{continue;}*field=requested-1;let frontier=job.work;let((result,receipt),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=RetainedWorkLedger::new(under);let result=job.advance(1,&mut work);(result,work.receipt())});assert!(!heap.overflowed);assert!(!result.unwrap().done);assert_eq!(receipt,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(job.work,frontier);assert_eq!(job.last_turn_work(),0);denied[axis]=true;}
   let(progress,after)=wallet.turn(1,|ledger|{let p=job.advance(1,ledger).unwrap();(p,ledger.receipt())});assert!(after.fits(remaining));remaining.maximum_items-=after.copied_items;remaining.maximum_copy_bytes-=after.copied_bytes;remaining.maximum_capacity_bytes-=after.retained_capacity_bytes;remaining.maximum_release_bytes-=after.released_bytes;if progress.done{complete=true;break;}assert!(after!=Default::default()||job.last_turn_work()>0,"finite original trace stock exhausted at turn{turn}: {:?}",job.next_work_demand());
  }assert!(complete);assert!(denied.into_iter().all(|value|value));let expected=row["foreground"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as u8).collect::<Vec<_>>();let segments=job.result().unwrap();let input=BitmapTraceInput{width:row["width"].as_u64().unwrap()as u32,height:row["height"].as_u64().unwrap()as u32,mask:&[]as&[u8],threshold:0.5,simplify_epsilon:0.0,max_pixels:9,max_edges:36,max_segments:45,max_work:1_000_000};assert_eq!(super::bounded_tests::foreground(segments,input),expected);let(mut owner,mask)=job.into_retirement();let mut release_denied=false;
  for _ in 0..1_000_000{if owner.terminal_is_empty(){break;}let copy=owner.next_copy_byte_demand().unwrap();let release=owner.next_release_byte_demand().unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(if copy>0{copy}else{release}).unwrap(),maximum_release_bytes:release,maximum_depth:owner.next_depth_demand().unwrap()};if release>0&&!release_denied{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(RetainedCloneGrant{maximum_release_bytes:release-1,..g}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));release_denied=true;}wallet.close_turn(semio_framework_value::RetirementDemand{copy_bytes:g.maximum_copy_bytes,capacity_bytes:g.maximum_capacity_bytes,release_bytes:g.maximum_release_bytes,depth:g.maximum_depth},|grant|owner.close_step(grant)).unwrap();}assert!(owner.terminal_is_empty());assert!(release_denied);wallet.close_owned(mask);
 }
}

#[path="../../../🛤️path/🎟️work/🧪️tests/🦀️.rs"]mod trace_funding;
#[test]fn neutral_trace_allocator_turn_separates_actual_and_semantic_work(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let row=&law["cases"][0];let mask=row["mask"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as u8).collect::<Vec<_>>();let mut job=BitmapTraceJob::new(BitmapTraceInput{width:row["width"].as_u64().unwrap()as u32,height:row["height"].as_u64().unwrap()as u32,mask,threshold:0.5,simplify_epsilon:row["epsilon"].as_f64().unwrap(),max_pixels:9,max_edges:36,max_segments:45,max_work:1_000_000});let stock=&law["stock"];let mut wallet=trace_funding::Wallet::from_grant(RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize},law["maxTurns"].as_u64().unwrap()as usize);let mut saw=false;
 for _ in 0..law["maxTurns"].as_u64().unwrap(){let before=job.progress().work;let(p,receipt)=wallet.turn(1,|work|{let p=job.advance(1,work).unwrap();(p,work.receipt())});assert_eq!(p.work-before,job.last_turn_semantic_work());if receipt.retained_capacity_bytes>0{assert_eq!(job.last_turn_semantic_work(),law["allocatorTurn"]["semanticWork"].as_u64().unwrap());assert_eq!(job.last_turn_work(),law["allocatorTurn"]["actualWork"].as_u64().unwrap());saw=true;break;}assert!(!p.done);}
 assert!(saw);wallet.close_owned(job);
}
